package com.meetspace.cache; import com.meetspace.dto.RoomDtos.Room; import org.springframework.stereotype.Component; import java.util.*;
@Component public class RoomIndex {private final Set<UUID> ids=new HashSet<>();private final Map<UUID,Room> entries=new HashMap<>();public synchronized boolean contains(UUID id){return ids.contains(id);}public synchronized Optional<Room> get(UUID id){return Optional.ofNullable(entries.get(id));}public synchronized void put(Room r){ids.add(r.id());entries.put(r.id(),r);}public synchronized void remove(UUID id){ids.remove(id);entries.remove(id);}public synchronized void clear(){ids.clear();entries.clear();}public synchronized int size(){return entries.size();}}